        // Group display order
        const FLAG_GROUP_ORDER = [
                "Messages",
                "Code",
                "Interactive Blocks",
                "Tools",
                "Attachments",
                "Web Search",
                "Answer Cards",
                "Header",
                "Branching",
        ];

        // Subsection display order (for groups with subsections)
        // Empty string "" renders flags without a subsection (e.g., INCLUDE_FILES)
        const FLAG_SUBSECTION_ORDER = {
                Messages: ["", "Annotations"],
                Attachments: ["", "Inline"],
                "Web Search": [""],
        };

        // ─── Files & media consolidation ─────────────────────────────────────
        // One panel group for every file. Images, diagrams and mini apps are files
        // like any other: they follow the Files switches and have no source toggles.
        FLAG_GROUP_ORDER.splice(
                FLAG_GROUP_ORDER.indexOf("Code") + 1,
                0,
                "Files & media",
        );
        FLAG_SUBSECTION_ORDER["Files & media"] = [""];

        // Headers that only repeat the master toggle above them are noise: the
        // annotations master already says "Annotations", the web-search master
        // already says "Web Features". Their flags render directly under the
        // master instead of under a second uppercase line.
        const FLATTENED_SUBSECTIONS = [
                "INCLUDE_TURN_NUMBERS",
                "INCLUDE_MODEL_INFO",
                "INCLUDE_TIMESTAMPS",
                "INCLUDE_MESSAGE_IDS",
                "INCLUDE_SEARCH_QUERIES",
                "INCLUDE_SEARCH_RESULTS",
                "COLLAPSIBLE_SEARCH_RESULTS",
                "INCLUDE_SOURCES",
                "INCLUDE_SOURCES_LIST",
                "COLLAPSIBLE_SOURCES_LIST",
        ];
        for (const flag of FLATTENED_SUBSECTIONS) {
                const meta = FLAG_METADATA[flag];
                if (meta) meta.subsection = "";
        }
        FLAG_SUBSECTION_ORDER.Messages = [""];

        // ═══════════════════════════════════════════════════════════════════════════
        // SETTINGS STORAGE (Per-Provider)
        // ═══════════════════════════════════════════════════════════════════════════
        // Per-provider defaults that differ from CONFIG. They sit between the global
        // defaults and the stored overrides, so a provider can ship a feature ON while
        // CONFIG stays conservative for everyone else.
        const PROVIDER_DEFAULTS = {
                // ChatGPT answers carry their own "thoughts" blocks; rendering them has been
                // the behavior since 10.22, so the toggle starts on instead of appearing to
                // remove content that was always there.
                ChatGPT: { INCLUDE_THINKING: true },
                // Widgets are Claude's own visualization format and the operator's default;
                // the group is opt-in everywhere else.
                Claude: { INCLUDE_FILES: true },
        };

        // Every file output the Files master controls for one export run.
        // (Images, web images, diagrams and mini apps are files too: they follow
        // FILE_DOWNLOAD_FILES and have no source toggle of their own.)

        const Settings = {
                /**
                 * Load provider-specific settings and merge with base CONFIG.
                 * @param {string} providerName - e.g., 'Claude', 'Grok', 'Arena'
                 * @returns {object} - Merged settings object
                 */
                load(providerName) {
                        if (!providerName) {
                                console.log(
                                        "[Chat Exporter] Settings.load() called without provider, returning CONFIG",
                                );
                                return { ...CONFIG };
                        }

                        try {
                                const key = CONFIG.SETTINGS_STORAGE_PREFIX + providerName;
                                const saved = GM_getValue(key, null);
                                console.log(
                                        "[Chat Exporter] Settings.load() for",
                                        providerName,
                                        "- raw storage:",
                                        saved,
                                );

                                const providerDefaults = PROVIDER_DEFAULTS[providerName] || {};
                                if (saved) {
                                        const overrides =
                                                typeof saved === "string" ? JSON.parse(saved) : saved;
                                        const merged = { ...CONFIG, ...providerDefaults, ...overrides };
                                        console.log(
                                                "[Chat Exporter] Settings.load() merged result - INCLUDE_USER_MESSAGES:",
                                                merged.INCLUDE_USER_MESSAGES,
                                                "INCLUDE_ASSISTANT_MESSAGES:",
                                                merged.INCLUDE_ASSISTANT_MESSAGES,
                                        );
                                        return merged;
                                }
                        } catch (e) {
                                console.warn("[Chat Exporter] Failed to load settings:", e);
                        }

                        console.log(
                                "[Chat Exporter] Settings.load() no overrides found, returning CONFIG defaults",
                        );
                        return {
                                ...CONFIG,
                                ...(PROVIDER_DEFAULTS[providerName] || {}),
                        };
                },

                /**
                 * Save provider-specific setting override.
                 * @param {string} providerName
                 * @param {string} flagName
                 * @param {boolean} value
                 */
                save(providerName, flagName, value) {
                        if (!providerName) return;

                        try {
                                const key = CONFIG.SETTINGS_STORAGE_PREFIX + providerName;
                                let overrides = {};

                                const saved = GM_getValue(key, null);
                                if (saved) {
                                        overrides = typeof saved === "string" ? JSON.parse(saved) : saved;
                                }

                                overrides[flagName] = value;
                                GM_setValue(key, overrides);
                                console.log(
                                        "[Chat Exporter] Settings.save() -",
                                        flagName,
                                        "=",
                                        value,
                                        "for",
                                        providerName,
                                );
                                console.log(
                                        "[Chat Exporter] Settings.save() - full overrides now:",
                                        overrides,
                                );
                        } catch (e) {
                                console.warn("[Chat Exporter] Failed to save settings:", e);
                        }
                },

                /**
                 * Get current effective value of a flag for a provider.
                 * @param {string} providerName
                 * @param {string} flagName
                 * @returns {boolean}
                 */
                get(providerName, flagName) {
                        const settings = this.load(providerName);
                        return settings[flagName];
                },

                /**
                 * Settings for an export run. `INCLUDE_FILES` is the one switch a user
                 * should need: when it is off, every file output is forced off for this
                 * run, while storage keeps the user's values so turning the master
                 * back on restores them.
                 * @param {string} providerName
                 * @returns {object}
                 */
                forExport(providerName) {
                        const settings = this.load(providerName);
                        if (settings.INCLUDE_FILES === false) {
                                settings.FILE_DOWNLOAD_FILES = false;
                                settings.FILE_CODE_BLOCK = false;
                                settings.FILE_RAW_CONTENT = false;
                                settings.FILE_CLICKABLE_LINK = false;
                        }
                        return settings;
                },

                /**
                 * Reset all settings for a provider to defaults.
                 * @param {string} providerName
                 */
                reset(providerName) {
                        if (!providerName) return;
                        const key = CONFIG.SETTINGS_STORAGE_PREFIX + providerName;
                        GM_deleteValue(key);
                        console.log(
                                "[Chat Exporter] Settings.reset() - cleared all overrides for",
                                providerName,
                        );
                },
        };

