                        const add = binaryLevel(mul, ["+", "-"]);
                        const rel = binaryLevel(add, ["<", ">", "<=", ">="]);
                        const eq = binaryLevel(rel, ["==", "!=", "===", "!=="]);
                        const and = binaryLevel(eq, ["&&"]);
                        const or = binaryLevel(and, ["||", "??"]);

